using LibraryManager.Data; using LibraryManager.Models; using Microsoft.EntityFrameworkCore; namespace LibraryManager.Services; public class BookService { public List<Book> All()=>new LibraryDbContext().Books.AsNoTracking().OrderBy(x=>x.Title).ToList(); public void Save(Book b){using var d=new LibraryDbContext();if(b.Id==0)d.Books.Add(b);else d.Books.Update(b);d.SaveChanges();} public void Delete(int id){using var d=new LibraryDbContext();var b=d.Books.Find(id);if(b==null)return;if(d.Loans.Any(x=>x.BookId==id))throw new InvalidOperationException("برای این کتاب سابقه امانت وجود دارد.");d.Remove(b);d.SaveChanges();} }